/* ==========================================================================
   Daily Slate — a Discord theme
   Ported from the "daily.dev" Chrome theme (dark navy, cool slate-blue)

   HOW TO USE
   - BetterDiscord: save this as DailySlate.theme.css in your BetterDiscord
     "themes" folder, then enable it under Settings > Themes.
   - Vencord: paste the whole file into Settings > QuickCSS.
   - Vanilla Discord (no client mod) can't load custom CSS at all — you need
     BetterDiscord, Vencord, or a similar client mod to apply this.

   The :root block below covers most of the UI on its own since it maps
   straight onto Discord's built-in theming variables. The selectors after
   it are extra polish (scrollbars, embeds, mentions, buttons) that use
   partial class matches so they survive Discord's hashed class names
   across updates — but they're the part most likely to need a tweak after
   a big Discord redesign.
   ========================================================================== */

:root {
  /* -- Core palette, taken directly from the source theme -------------- */
  --slate-bg:          #0F1218; /* frame / ntp_background */
  --slate-bg-deep:      #0B0D12;
  --slate-bg-raised:    #14171D;
  --slate-bg-panel:     #171A21;
  --slate-bg-input:     #1E2229; /* omnibox_background */
  --slate-bg-accent:    #252537; /* ntp_link */
  --slate-bg-float:     #1A1E27;

  --slate-text:         #CDD4E3; /* bookmark_text */
  --slate-text-muted:   #7E87A3;
  --slate-text-dim:     #A9B2CD; /* ntp_text / tab_background_text */
  --slate-header:       #FFFFFF; /* tab_text / toolbar_text */
  --slate-header-alt:   #C1C1CD; /* ntp_header */
  --slate-link:         #8FA0D6;

  --slate-brand:        #6772AE;
  --slate-brand-hover:  #7986C4;
  --slate-brand-active: #545F94;

  --slate-border: rgba(169, 178, 205, 0.08);
}

/* -- Map the palette onto Discord's theming variables -------------------- */
:root {
  --background-primary: var(--slate-bg);
  --background-secondary: var(--slate-bg-raised);
  --background-secondary-alt: var(--slate-bg-panel);
  --background-tertiary: var(--slate-bg-deep);
  --background-accent: var(--slate-bg-accent);
  --background-floating: var(--slate-bg-float);
  --background-mobile-primary: var(--slate-bg);
  --background-mobile-secondary: var(--slate-bg-raised);
  --channeltextarea-background: var(--slate-bg-input) !important;

  --background-modifier-hover: rgba(169, 178, 205, 0.06);
  --background-modifier-active: rgba(169, 178, 205, 0.1);
  --background-modifier-selected: rgba(169, 178, 205, 0.14);
  --background-modifier-accent: var(--slate-border);

  --text-normal: var(--slate-text);
  --text-muted: var(--slate-text-muted);
  --text-link: var(--slate-link);
  --header-primary: var(--slate-header);
  --header-secondary: var(--slate-header-alt);

  --interactive-normal: var(--slate-text-dim);
  --interactive-hover: var(--slate-text);
  --interactive-active: var(--slate-header);
  --interactive-muted: #4B5164;

  --brand-experiment: var(--slate-brand);
  --brand-experiment-560: var(--slate-brand-hover);
  --brand-experiment-600: var(--slate-brand-active);
  --brand-500: var(--slate-brand);
  --brand-560: var(--slate-brand-hover);

  --scrollbar-thin-thumb: var(--slate-bg-accent);
  --scrollbar-thin-track: transparent;
  --scrollbar-auto-thumb: var(--slate-bg-accent);
  --scrollbar-auto-track: var(--slate-bg-deep);

  --elevation-low: none;
  --elevation-medium: none;
  --elevation-high: none;
}

/* -- App frame & server rail ---------------------------------------------- */
[class*="guilds_"],
[class*="chrome_"],
[class*="platformWindows_"] {
  background: var(--slate-bg-deep) !important;
}

[class*="pill_"] {
  background: var(--slate-brand) !important;
}

/* -- Message area ----------------------------------------------------------- */
[class*="chat_"] {
  background: var(--slate-bg);
}

[class*="message_"]:hover {
  background: rgba(169, 178, 205, 0.03) !important;
}

/* -- Code blocks & inline code ------------------------------------------------ */
code, pre {
  background: var(--slate-bg-deep) !important;
  border: 1px solid var(--slate-border) !important;
  color: var(--slate-text) !important;
}

/* -- Blockquotes --------------------------------------------------------------- */
[class*="blockquoteContainer_"] {
  border-left: 3px solid var(--slate-bg-accent);
}

/* -- Embeds ---------------------------------------------------------------------- */
[class*="embedFull_"],
[class*="embed_"] {
  background: var(--slate-bg-raised) !important;
  border-color: var(--slate-border) !important;
}

/* -- Mentions ------------------------------------------------------------------------ */
[class*="mention_"] {
  background: rgba(103, 114, 174, 0.3) !important;
  color: #C7CEF0 !important;
}

[class*="mention_"]:hover {
  background: rgba(103, 114, 174, 0.5) !important;
}

/* -- Spoilers ---------------------------------------------------------------------------- */
[class*="spoilerText_"] {
  background: var(--slate-bg-accent) !important;
}

/* -- Filled brand buttons ------------------------------------------------------------------- */
[class*="lookFilled_"][class*="colorBrand_"] {
  background: var(--slate-brand) !important;
}

[class*="lookFilled_"][class*="colorBrand_"]:hover {
  background: var(--slate-brand-hover) !important;
}

/* -- Unread badges -------------------------------------------------------------------------------- */
[class*="numberBadge_"] {
  background: var(--slate-brand) !important;
}

/* -- Scrollbars ----------------------------------------------------------------------------------------- */
* {
  scrollbar-color: var(--slate-bg-accent) transparent;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-thumb {
  background: var(--slate-bg-accent);
  border-radius: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}
